1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Quote: base premiums, simplest first ---
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result).toEqual({ results: [{ premium: 5 }] });
13	  });
14	  it.todo("a plain sword → premium 115 G (100 base + 10 first insurance + 5 fee)");
15	  it.todo("a plain amulet → premium 71 G (60 base + 6 first insurance + 5 fee)");
16	  it.todo("a plain staff → premium 93 G (80 base + 8 first insurance + 5 fee)");
17	  it.todo("a plain potion → premium 49 G (40 base + 4 first insurance + 5 fee)");
18	  it.todo("a single rune → base premium 25 G");
19	
20	  // --- Building block of 3 alike components ---
21	  it.todo("2 runes → 50 G base premium");
22	  it.todo("3 runes → 60 G base premium (block applies)");
23	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
24	  it.todo("7 runes → 175 G base premium");
25	
26	  // --- "Alike" components (❓ same type, not same family) ---
27	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
28	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
29	
30	  // --- Premium modifiers in isolation ---
31	  it.todo("cursed sword adds a 50 % risk surcharge on the item base premium");
32	  it.todo("sword with enchantment 5 adds a 30 % high-enchantment surcharge (threshold)");
33	  it.todo("sword with enchantment 4 gets no high-enchantment surcharge");
34	  it.todo("cursed sword with enchantment 5 gets both surcharges");
35	  it.todo("customer with exactly 2 years with MHPCO receives the 20 % loyalty discount");
36	  it.todo("customer with 1 year with MHPCO receives no loyalty discount");
37	  it.todo("every quote carries the 10 % initial assessment surcharge (first insurance)");
38	  it.todo("second quote in a scenario receives the 15 % follow-up contract discount");
39	
40	  // --- Modifier scope on multi-item policies (❓ item-specific vs policy-wide) ---
41	  it.todo(
42	    "cursed sword (100 G) + plain amulet (60 G) → base 160 G, curse adds 50 G → 210 G before further modifiers and fee",
43	  );
44	
45	  // --- Rounding in the MHPCO's favor ---
46	  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
47	  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
48	
49	  // --- Integration examples ---
50	  it.todo("newcomer with a cursed sword (0 years, steel, enchantment 3) → premium 165 G");
51	  it.todo(
52	    "long-standing customer's second contract (3 years, cursed sword enchantment 7) → premium 160 G",
53	  );
54	
55	  // --- Claims: standard reimbursement ---
56	  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
57	  it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G");
58	
59	  // --- Claims: special clauses ---
60	  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full, then deductible)");
61	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
62	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
63	  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
64	
65	  // --- Deductible per damage event ---
66	  it.todo(
67	    "dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (deductible once per damaged item)",
68	  );
69	
70	  // --- Insurance sum and cap ---
71	  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
72	  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
73	  it.todo("a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
74	  it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G");
75	
76	  // --- Cap exhaustion across successive claims ---
77	  it.todo("sword (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
78	  it.todo("sword (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");
79	
80	  // --- Multiple items of the same type (❓ two swords) ---
81	  it.todo(
82	    "two swords insured, damages contains two sword entries → each treated as a separate damage with its own deductible",
83	  );
84	  it.todo(
85	    "more damage entries of a type than the policy covers (two sword damages, one sword insured) → error",
86	  );
87	
88	  // --- Error cases ---
89	  it.todo("quote includes an item with an unknown type (broomstick) → error");
90	  it.todo("claim references an item not part of the policy (amulet damaged, only sword insured) → error");
91	  it.todo("claim references a damage entry with an unknown item type → error");
92	  it.todo("claim contains a damage entry with amount -200 → error");
93	
94	  // --- CLI ---
95	  it.todo("CLI reads a scenario from stdin and writes {results: [...]} to stdout (schema example)");
96	  it.todo("CLI exits with a non-zero status code and writes an error to stderr on an unknown item type");
97	  it.todo("CLI exits with a non-zero status code and writes an error to stderr on an invalid claim");
98	});
